using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.SGR.Casas;using GraphApi.Services.SGR.Casas;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.SGR.Casas{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Casas: creación, actualización y eliminación.")]    public class CasasMutation    {        [Authorize]        [GraphQLName("createCasas")]        [GraphQLDescription("Crea un nuevo Casa usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadCasas> CreateCasasAsync(            [GraphQLDescription("Datos necesarios para crear el Casa.")]            clCreateCasas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Casa.")]            ICasasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateCasas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateCasas")]        [GraphQLDescription("Actualiza los campos especificados de un Casa existente.")]        public async Task<clReadCasas?> UpdateCasasAsync(            [GraphQLDescription("Datos del Casa a actualizar.")]            clUpdateCasas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Casa.")]            ICasasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateCasas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteCasas")]        [GraphQLDescription("Elimina un Casa por su ID.")]        public async Task<bool> delCasasAsync(            [GraphQLDescription("ID del Casa a eliminar.")]            int nCasasID,            [Service]            [GraphQLDescription("Servicio para operaciones de Casa.")]            ICasasService objService        )        {            return await objService.DeleteCasas(nCasasID);        }    }}